/**
 * Whisk Offline Mermaid Diagram Renderer Engine
 */
(function(window) {
    var mermaid = {
        initialize: function(config) {
            console.log("Offline Mermaid initialized with config", config);
            this.config = config || {};
            this.renderAll();
        },
        renderAll: function() {
            var elems = document.querySelectorAll('.mermaid');
            for (var i = 0; i < elems.length; i++) {
                var el = elems[i];
                var code = el.innerText || el.textContent;
                var isDark = (this.config.theme === 'dark');
                var svg = this.parseAndRenderSvg(code.trim(), isDark);
                el.innerHTML = svg;
            }
        },
        parseAndRenderSvg: function(text, isDark) {
            var bgColor = isDark ? '#1e293b' : '#f8fafc';
            var boxBg = isDark ? '#0f172a' : '#ffffff';
            var textColor = isDark ? '#f8fafc' : '#0f172a';
            var strokeColor = isDark ? '#38bdf8' : '#2563eb';
            var arrowColor = isDark ? '#94a3b8' : '#64748b';

            var lines = text.split('\n');
            var nodes = {};
            var edges = [];

            for (var i = 0; i < lines.length; i++) {
                var line = lines[i].trim();
                if (!line || line.indexOf('graph') === 0 || line.indexOf('flowchart') === 0) continue;

                var edgeMatch = line.match(/(.*?)\s*(-->|---|==>|\.->)\s*(.*)/);
                if (edgeMatch) {
                    var left = edgeMatch[1].trim();
                    var arrow = edgeMatch[2].trim();
                    var right = edgeMatch[3].trim();

                    var leftParsed = this.parseNode(left);
                    var rightParsed = this.parseNode(right);

                    nodes[leftParsed.id] = leftParsed.label || nodes[leftParsed.id] || leftParsed.id;
                    nodes[rightParsed.id] = rightParsed.label || nodes[rightParsed.id] || rightParsed.id;

                    edges.push({ from: leftParsed.id, to: rightParsed.id, type: arrow });
                } else {
                    var singleParsed = this.parseNode(line);
                    if (singleParsed.id) {
                        nodes[singleParsed.id] = singleParsed.label || singleParsed.id;
                    }
                }
            }

            var nodeKeys = Object.keys(nodes);
            if (nodeKeys.length === 0) {
                return '<div style="color:' + textColor + ';padding:12px;font-size:14px;">' + this.escapeHtml(text) + '</div>';
            }

            var nodeWidth = 140;
            var nodeHeight = 45;
            var gapX = 60;
            var gapY = 80;

            var cols = Math.min(nodeKeys.length, 3);
            var rows = Math.ceil(nodeKeys.length / cols);

            var svgWidth = Math.max(400, cols * (nodeWidth + gapX) + gapX);
            var svgHeight = rows * (nodeHeight + gapY) + gapY;

            var posMap = {};
            for (var idx = 0; idx < nodeKeys.length; idx++) {
                var key = nodeKeys[idx];
                var r = Math.floor(idx / cols);
                var c = idx % cols;
                var x = gapX + c * (nodeWidth + gapX) + nodeWidth / 2;
                var y = gapY + r * (nodeHeight + gapY) + nodeHeight / 2;
                posMap[key] = { x: x, y: y };
            }

            var svgHtml = '<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 ' + svgWidth + ' ' + svgHeight + '" style="background:transparent;width:100%;height:auto;">';
            svgHtml += '<defs><marker id="arrow" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M 0 0 L 10 5 L 0 10 z" fill="' + arrowColor + '"/></marker></defs>';

            for (var e = 0; e < edges.length; e++) {
                var edge = edges[e];
                var p1 = posMap[edge.from];
                var p2 = posMap[edge.to];
                if (p1 && p2) {
                    svgHtml += '<line x1="' + p1.x + '" y1="' + p1.y + '" x2="' + p2.x + '" y2="' + p2.y + '" stroke="' + strokeColor + '" stroke-width="2" marker-end="url(#arrow)" stroke-dasharray="' + (edge.type === '.->' ? '4,4' : 'none') + '"/>';
                }
            }

            for (var k = 0; k < nodeKeys.length; k++) {
                var nk = nodeKeys[k];
                var p = posMap[nk];
                var labelText = nodes[nk];

                svgHtml += '<g transform="translate(' + (p.x - nodeWidth/2) + ',' + (p.y - nodeHeight/2) + ')">';
                svgHtml += '<rect width="' + nodeWidth + '" height="' + nodeHeight + '" rx="10" ry="10" fill="' + boxBg + '" stroke="' + strokeColor + '" stroke-width="2"/>';
                svgHtml += '<text x="' + (nodeWidth/2) + '" y="' + (nodeHeight/2 + 5) + '" fill="' + textColor + '" font-size="13" font-weight="600" text-anchor="middle" font-family="system-ui, sans-serif">' + this.escapeHtml(labelText) + '</text>';
                svgHtml += '</g>';
            }

            svgHtml += '</svg>';
            return svgHtml;
        },
        parseNode: function(str) {
            var m = str.match(/([A-Za-z0-9_]+)\s*(\[|\(|\{|\{\{)(.*?)(\]|\)|\}|\}\})/);
            if (m) {
                return { id: m[1], label: m[3] };
            }
            var cleanId = str.replace(/[^A-Za-z0-9_]/g, '');
            return { id: cleanId || str, label: str };
        },
        escapeHtml: function(text) {
            return String(text).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
        }
    };

    window.mermaid = mermaid;
    document.addEventListener("DOMContentLoaded", function() {
        if (window.mermaid) window.mermaid.renderAll();
    });
})(window);
